"""Render the whole-three-ward fixed-cost demand recovery comparison."""
from pathlib import Path
import os,json,html,hashlib,datetime as dt
import pandas as pd,numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[2];P=ROOT/'data/processed/three_ward_vehicle_demand_recovery_v1';R=ROOT/'data/exp/estimation/three_ward_vehicle_demand_recovery_v1';A=ROOT/'data/exp/feasibility-check/three_ward_vehicle_demand_coverage_audit_v1'
ARMS=['U_reference','C_coarse_only','I_intrazonal_only'];SHORT=['U: unchanged','C: coarse OD','I: intrazonal'];CN={'U_reference':'U 原参照','C_coarse_only':'C 仅补粗OD','I_intrazonal_only':'I 仅补区内短途'}
def dump(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def sha(p):
 h=hashlib.sha256()
 with p.open('rb')as f:
  for b in iter(lambda:f.read(8*1024*1024),b''):h.update(b)
 return h.hexdigest()
def main():
 s=json.loads((R/'summary.json').read_text());validation=json.loads((R/'validation.json').read_text());prep=json.loads((R/'preparation_summary.json').read_text());route=json.loads((R/'routing_validation.json').read_text());assert validation['passed']and route['passed']and all(prep['checks'].values());met=pd.read_csv(P/'primary_small12h_metrics.csv');eff=pd.read_csv(P/'separate_demand_effects.csv');routes=pd.read_csv(P/'increment_route_diagnostics.csv');gates=pd.read_csv(P/'joint_development_gate.csv')
 def m(arm,cls,role='all85_development'):return met[met.arm.eq(arm)&met.road_class.eq(cls)&met.evaluation_role.eq(role)].iloc[0]
 def e(arm,cls,role='all85_development'):return eff[eff.arm.eq(arm)&eff.road_class.eq(cls)&eff.evaluation_role.eq(role)].iloc[0]
 def link(n,label):return f'<a href="{os.path.relpath(P/n,R)}">{html.escape(label)}</a>'
 plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'figure.facecolor':'#f5f8fa'});fig,axes=plt.subplots(1,2,figsize=(12,5.1));x=np.arange(3)
 for ax,measure,title,yl in zip(axes,['prediction_observation_ratio','wape'],['Count totals: ratio can hide spatial error','Weighted absolute percentage error (lower is better)'],['Modeled / observed small-vehicle passages (%)','WAPE (%)']):
  for off,cls,color,label in [(-.18,'ordinary','#bc8841','Ordinary roads (53)'),(.18,'expressway','#367f99','Expressways (32)')]:
   vals=[m(arm,cls)[measure]*100 for arm in ARMS];bars=ax.bar(x+off,vals,.34,color=color,label=label)
   for bar,y in zip(bars,vals):ax.text(bar.get_x()+bar.get_width()/2,y+2,f'{y:.2f}',ha='center',fontsize=8)
  if measure=='prediction_observation_ratio':ax.axhline(100,color='#9ba6ac',ls='--',lw=1)
  ax.set_xticks(x,SHORT);ax.set(ylim=(0,115),title=title,ylabel=yl);ax.legend(fontsize=8,frameon=False);ax.grid(axis='y',alpha=.1)
 fig.tight_layout(rect=[0,.18,1,.94]);fig.suptitle('Fixed U costs: separate demand additions, unchanged 85 development screenlines',fontsize=12);fig.text(.5,.035,'Both directions, 07:00–19:00, small-vehicle observations. C and I are separate additions; no combined arm.\nOriginal demand, physical roads, turn graph, costs and external-through branches stay fixed. No congestion feedback.\nSource additions use conditional spatial and clock weights; these are not measured vehicle routes or an independent validation.',ha='center',fontsize=8);fig.savefig(R/'demand_recovery_comparison.png',dpi=170);plt.close(fig)
 fig,(ax,bx)=plt.subplots(1,2,figsize=(12,4.8));roles=['development_original_calibration65','development_previously_inspected20'];labels=['Original 65','Inspected 20'];colors=['#bc8841','#367f99']
 for i,(arm,title)in enumerate(zip(ARMS[1:],['C: coarse OD addition','I: intrazonal addition'])):
  aa=[ax,bx][i]
  for off,cls,color,label in [(-.16,'ordinary',colors[0],'Ordinary'),(.16,'expressway',colors[1],'Expressway')]:
   vals=[e(arm,cls,r).wape_change*100 for r in roles];bars=aa.bar(np.arange(2)+off,vals,.3,color=color,label=label)
   for bar,y in zip(bars,vals):aa.text(bar.get_x()+bar.get_width()/2,y+(.07 if y>=0 else -.07),f'{y:+.3f}',ha='center',va='bottom'if y>=0 else'top',fontsize=8)
  aa.axhline(0,color='#78919d',lw=1);aa.set_xticks(np.arange(2),labels);aa.set(title=title,ylabel='WAPE change versus U (percentage points)',ylim=(-3.6,1.3));aa.legend(frameon=False,fontsize=8);aa.grid(axis='y',alpha=.12)
 fig.tight_layout(rect=[0,.2,1,1]);fig.text(.5,.035,'Negative = improvement. Both original groups are development, with no re-splitting or sealed test.\nJoint relative gate: neither road class may worsen in either group, and at least one strict improvement.\nA passing gate does not establish adequate ordinary-road traffic volumes, actual congestion or correct local routes.',ha='center',fontsize=8);fig.savefig(R/'development_group_effects.png',dpi=170);plt.close(fig)
 mainrows=''.join(f'<tr><td>{CN[a]}</td><td>{m(a,"ordinary").prediction_observation_ratio:.2%}</td><td>{m(a,"ordinary").wape:.2%}</td><td>{m(a,"expressway").prediction_observation_ratio:.2%}</td><td>{m(a,"expressway").wape:.2%}</td></tr>'for a in ARMS)
 grouprows=''.join(f'<tr><td>{CN[r.arm]}</td><td>{"原65开发组"if r.evaluation_role.endswith("calibration65")else"原20开发组"}</td><td>{"普通道路"if r.road_class=="ordinary"else"高速"}</td><td>{r.wape_change*100:+.3f}</td><td>{r.new_prediction_observation_ratio:.2%}</td></tr>'for r in eff[~eff.evaluation_role.eq('all85_development')].itertuples())
 rr=routes[routes.period.eq('daily')];routerows=''.join(f'<tr><td>{CN[r.arm]}</td><td>{r.added_candidate_trips:,.1f}</td><td>{r.motorway_using_candidate_share:.2%}</td><td>{r.mean_route_km:.2f}</td><td>{r.weighted_p95_route_km:.2f}</td></tr>'for r in rr.itertuples());C=e('C_coarse_only','ordinary');I=e('I_intrazonal_only','ordinary');c65=e('C_coarse_only','expressway',roles[0]);short=rr[rr.arm.eq('I_intrazonal_only')].iloc[0];coarse=rr[rr.arm.eq('C_coarse_only')].iloc[0]
 doc=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>三区固定成本需求补入对照</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#edf2f5;color:#233e4b;font:16px/1.75 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}}main{{max-width:1120px;margin:30px auto;padding:32px;background:#fff;border-radius:16px}}h1{{font-size:30px;line-height:1.4}}h2{{font-size:22px;margin-top:30px}}p{{margin:14px 0}}a{{color:#146587}}.meta{{color:#657b85;font-size:14px}}.lead{{background:#e9f2f5;border-left:5px solid #367f99;padding:18px}}.note{{background:#fff3df;padding:15px;border-radius:8px}}.cards{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:20px 0}}.card{{padding:18px;background:#f0f5f6;border-radius:9px}}.big{{font-size:27px;font-weight:700;display:block}}img{{max-width:100%;height:auto;border:1px solid #dce6e9}}.scroll{{overflow:auto}}table{{width:100%;border-collapse:collapse;font-size:14px}}th,td{{padding:10px;border-bottom:1px solid #dce6e9;text-align:left;vertical-align:top}}th{{background:#eef3f5}}code{{overflow-wrap:anywhere}}@media(max-width:700px){{main{{margin:0;padding:20px 14px;border-radius:0}}h1{{font-size:25px}}.cards{{grid-template-columns:1fr}}table{{min-width:660px}}}}</style><main><p class="meta">2026-10-18 JST · 千代田区／中央区／港区及必要道路连接 · 已完成固定成本对照</p><h1>补入已知暂留需求，普通道路仍明显缺量</h1><div class="lead">粗尺度OD和区内短途两组均完成，源量全部可达且守恒。两项对普通道路的改善都很小；粗OD主要增加高速负载，未通过两类道路共同改善规则。短途组通过相对规则，但不能据此认证正常交通基线或拥堵预测。</div><div class="cards"><div class="card"><span class="big">8.45% → 8.78%</span>补粗OD后的普通道路总量比</div><div class="card"><span class="big">8.45% → 8.64%</span>补区内短途后的普通道路总量比</div><div class="card"><span class="big">83个源入口</span>一次共享路径计算，约{route['elapsed_s']:.1f}秒<br>重放原U路径成本差为0</div></div><p>固定原U单路径成本F0_R0：没有收费偏好或随机扰动，没有调速、调容量或拟合OD倍数。三组共用原路网、通行权限和转向约束。C、I分别相对U比较，本轮没有合并补入组。</p>
<h2>1. 普通道路与高速是否更接近观测</h2><p>以下为85个既有观测断面中的53个普通道路、32个高速断面，双向小型车07–19h。原65和已查看20均为开发数据，未改变划分。</p><div class="scroll"><table><tr><th>组</th><th>普通道路模型／观测</th><th>普通道路WAPE</th><th>高速模型／观测</th><th>高速WAPE</th></tr>{mainrows}</table></div><img src="demand_recovery_comparison.png" alt="Separate demand additions: modeled passage totals and WAPE on ordinary roads and expressways"><p>总量比只比较总和；WAPE是各断面绝对误差之和除以观测之和，越低越好。高速总量比上升，不代表每个位置都更准确。</p><p><b>C粗OD：</b>普通道路新增约{C.added_passages:,.1f}次断面通过量，仅填补原普通道路总量缺口的{C.baseline_aggregate_shortfall_recovered_fraction:.2%}，53断面中20个误差减少、0个变差。高速新增约{e('C_coarse_only','expressway').added_passages:,.1f}次通过量，但22个断面改善、9个变差，整体WAPE基本不变。</p><p><b>I区内短途：</b>普通道路新增约{I.added_passages:,.1f}次通过量，填补原缺口{I.baseline_aggregate_shortfall_recovered_fraction:.2%}，27个断面误差减少、0个变差；高速变化小，整体WAPE略有下降。</p><p class="note">“填补缺口”以同一批普通道路断面通过量计算；不是把新增行程数与观测通过量相减。新增需求是源量有依据的驾驶候选，车型和小时分布仍是条件解释。</p>
<h2>2. 为什么粗OD没有解决普通道路缺量</h2><p>168对无细种子中分区OD合计24,461次／日，按官方子分区等权，再按原道路入口等权分配。该分支的模型路径平均约{coarse.mean_route_km:.2f} km，{coarse.motorway_using_candidate_share:.2%}的候选权重使用高速；许多源伙伴位于较远地区。因而它主要增加长距离进出三区的高速负载，对普通道路断面作用很小。</p><p>14个同细分区暂留OD合计6,844.4次／日，平均模型路径{short.mean_route_km:.2f} km，P95为{short.weighted_p95_route_km:.2f} km，最大{short.maximum_route_km:.2f} km；其中{short.motorway_using_candidate_share:.2%}权重使用高速。既有分散入口加固定U成本可能产生出区绕行，不能把“同分区”当作已核验的真实短途路线，更不能把该高速占比当成观测行为。</p><div class="scroll"><table><tr><th>组</th><th>新增候选／日</th><th>路径使用高速占比</th><th>平均模型里程km</th><th>P95 km</th></tr>{routerows}</table></div><p>远端粗OD的里程只覆盖道路模型范围内的门户到入口段，并非完整出行长度；区内路径允许沿既有合法网络出区。日输入不等于12小时通过量，模型没有排队或流量—速度反馈。</p>
<h2>3. 相对改善规则：粗OD未过，短途组通过但改善有限</h2><p>预先规则要求：原65和原20开发组中，普通道路与高速的小型车12h WAPE均不恶化，且至少一项严格改善。<b>C粗OD未通过</b>：原65组高速WAPE增加{c65.wape_change*100:.3f}个百分点。<b>I短途组通过</b>，两类道路在两组中均略改善；这只是相对变化，普通道路总量仍仅约观测的8.6%。</p><img src="development_group_effects.png" alt="Separate road-class WAPE changes in both original development groups"><details><summary>查看原65＋20开发组逐类比较</summary><div class="scroll"><table><tr><th>组</th><th>开发组</th><th>道路</th><th>WAPE变化pp</th><th>补入后总量比</th></tr>{grouprows}</table></div></details><p>两组均未新增独立验证证据，未对观测重划分或重新封存。粗OD的源量仍有价值，但这套空间分配不直接替换基线；短途组保留为需求敏感性分支，不能宣布已完成交通校准。</p>
<h2>4. 外部穿越、车型和未知时刻均保留</h2><p>原“无远端穿越”和“条件远端穿越”两分支保持原值。C或I的同一增量分别加到各自原分支，两个外部版本间差值核验残差为{s['maximum_preserved_external_branch_residual']:.2g}。没有把区域远端OD整体灌入三区，也没有追加货车、出租车空驶或域外居民的假设倍率。</p><p>粗OD有约{prep['by_increment']['coarse']['unknown_clock_proxy_daily']:.1f}次／日、短途有约{prep['by_increment']['intrazonal']['unknown_clock_proxy_daily']:.1f}次／日为条件推算的未知时刻权重，未塞入高峰；它们已经包含在每日总量中，不是额外加量。原4,638次伙伴位置不明、其他域外暂留、车型OD及5-3精确驾驶口径问题继续单列。07–19h新增候选分别约19,073.7与5,104.4次，仍沿用原汽车人次时钟代理。</p><p>2018需求、2021普通日观测与2026路网的年份和调查对象差异保留。未追加水动力模拟、未计算受影响人数，未改变封存测试或训练任何模型。</p>
<h2>5. 本轮判断与核验</h2><p><b>这两项已知暂留需求不是普通道路严重缺量的主要解释。</b>在固定U成本与所声明位置假设下，两组只能填补普通道路总量缺口约0.36%与0.21%。这是条件实验的解释范围，不能推出所有可能的需求位置或路线都无效。</p><p>后续应先明确普通道路的车辆需求与边界流量约束，保留负荷情景，再决定交通基线怎样进入暴雨对照；不建议继续用统一倍数或成本微调把缺量强行抹平。当前不能发布可信的绝对拥堵时间或受影响人数结论。</p><p>准备{len(prep['checks'])}项、路由{len(route['checks'])}项、比较{len(validation['checks'])}项完整性核验全部通过；新增源控制与原已路由需求不重复，源量、五个时段和节点分量守恒，新增需求无不可达项。最大节点分量残差{route['maximum_component_flow_residual']:.2g}；83行既有U端点最优成本完全重放，差值0秒。既有源数据、原路网和成本SHA-256均保持不变。</p><p>复现顺序：<code>src/preprocessing/prepare_vehicle_demand_recovery_v1.py</code> → <code>src/analyses/run_vehicle_demand_recovery_v1.py</code> → <code>src/analyses/evaluate_vehicle_demand_recovery_v1.py</code> → <code>src/analyses/report_vehicle_demand_recovery_v1.py</code>。</p><p>{link('protocol.json','预先对照规则')} · {link('input_bindings.json','冻结输入哈希')} · {link('source_control_conservation.csv','源控制守恒')} · {link('conditional_addition_ledger.csv','条件分配与原行号')} · {link('primary_small12h_metrics.csv','主指标')} · {link('separate_demand_effects.csv','分离效应')} · {link('paired_screenline_changes.csv','固定断面变化')} · {link('flow_metrics.csv','全部时段与原穿越分支')} · {link('increment_route_diagnostics.csv','里程与高速使用诊断')} · {link('joint_development_gate.csv','相对改善规则')} · <a href="routing_validation.json">路由核验</a> · <a href="validation.json">比较核验</a> · <a href="summary.json">机器可读汇总</a> · <a href="{os.path.relpath(A/'review.html',R)}">上一轮需求与车型审计</a></p><p class="meta">统计经过本项目处理。底层道路 © OpenStreetMap contributors / ODbL；PT与道路普查出处沿用源审计。Framelog：MILI-D-20261018-006。AnaSOP、Git、DVC及既有实验未改写。</p></main></html>'''
 (R/'review.html').write_text(doc);files=list(P.glob('*'))+list(R.glob('*'))+[ROOT/'src/preprocessing/prepare_vehicle_demand_recovery_v1.py']+[ROOT/'src/analyses'/n for n in ['run_vehicle_demand_recovery_v1.py','evaluate_vehicle_demand_recovery_v1.py','report_vehicle_demand_recovery_v1.py','validate_vehicle_demand_recovery_browser_v1.cjs']];dump(R/'delivery_manifest.json',{'created_utc':dt.datetime.now(dt.timezone.utc).isoformat(),'files':[{'path':str(p.relative_to(ROOT)),'bytes':p.stat().st_size,'sha256':sha(p)}for p in files if p.is_file()and p.name not in ['delivery_manifest.json','browser_validation.json','review_desktop.png','review_mobile.png']]});print('Fixed-cost demand recovery report ready.')
if __name__=='__main__':main()
